import React, { useEffect, useState } from 'react';
import { connect } from 'react-redux';
import { Card, CardBody, FormGroup, Form, Input, Row, Col } from 'reactstrap';
// Material UI
import Paper from '@material-ui/core/Paper';
import { makeStyles } from '@material-ui/core/styles';
import Tabs from '@material-ui/core/Tabs';
import Tab from '@material-ui/core/Tab';
import LockOpenIcon from '@material-ui/icons/LockOpen';
import PersonPinIcon from '@material-ui/icons/PersonPin';
import Box from '@material-ui/core/Box';
// MUI
import ReactDatePicker from 'react-datepicker';
import moment from 'moment';
import validator from 'validator';
import constants from '../../../config/constants';
import {
  closeToast,
  fetchUserService,
  showToast,
  updateUserService,
  updatePasswordService,
} from '../../../actions/admin/auth';
import { store } from '../../..';
import { formResMessage, getGlobalSchoolUtils } from '../../../utils/commonFunc';
import ChangePassword from './ChangePassword';
import CustomButton from '../../../components/CustomButton';
import useAppProvider from 'providers/useAppProvider';

const profileImgModule = require('assets/img/damir-bosnjak.jpg');
const profileImgSrc = profileImgModule?.default || profileImgModule;

export function TabPanel(props) {
  const { children, value, index, ...other } = props;
  return (
    <div
      role="tabpanel"
      hidden={value !== index}
      id={`simple-tabpanel-${index}`}
      aria-labelledby={`simple-tab-${index}`}
      {...other}>
      {value === index && <Box p={0.5}>{children}</Box>}
    </div>
  );
}

export function a11yProps(index) {
  return {
    id: `simple-tab-${index}`,
    'aria-controls': `simple-tabpanel-${index}`,
  };
}

const useStyles = makeStyles({
  root: {
    flexGrow: 1,
  },
});

const stateObj = {
  data: {
    name: '',
    email: '',
    gender: '',
    dateOfBirth: '',
    qualification: '',
    joiningDateTime: '',
    designation: '',
    department: '',
    totalExperience: '',
  },
  errors: {},
  loading: false,
};

let timer;
const MyProfile = props => {
  const { buttonColor, buttonBorderColor } = useAppProvider();
  const classes = useStyles();
  const [value, setValue] = React.useState(0);
  const [stateVal, setState] = useState(stateObj);

  const handleTabChange = (event, newValue) => {
    setValue(newValue);
  };

  useEffect(() => {
    if (props.loggedUserRole === constants.roles.SA) {
      store.dispatch(showToast('User profile is only for admin and teacher. We are navigating you back', 'warning'));
      timer = setTimeout(() => {
        store.dispatch(closeToast());
        props.history.goBack();
      }, 4000);
    } else {
      props.fetchUser({
        userId: props.loggedUserId,
        token: props.loggedUserToken,
        userRole: props.loggedUserRole,
      });
    }

    return () => {
      if (timer) {
        clearTimeout(timer);
      }
    };
  }, [props.loggedUserRole, props.fetchUser]);

  useEffect(() => {
    const user = props.userProfile;
    setState(prevState => ({
      ...prevState,
      data: {
        ...prevState.data,
        name: user.name,
        email: user.email,
        gender: user.gender,
        dateOfBirth: user.dateOfBirth,
        qualification: user.qualification,
        joiningDateTime: user.joiningDateTime,
        designation: user.designation,
        department: user.department,
        totalExperience: user.totalExperience,
      },
    }));
  }, [props.userProfile]);

  const handleChange = e => {
    e.persist();
    setState(prevState => ({
      ...prevState,
      data: { ...prevState.data, [e.target.name]: e.target.value },
    }));
  };

  const handleDateChange = (name, date) => {
    setState(prevState => ({
      ...prevState,
      data: {
        ...prevState.data,
        [name]: moment(moment(date).format('YYYY-MM-DD HH:mm:ss')).valueOf(),
      },
    }));
  };

  const handleSubmit = e => {
    e.preventDefault();
    const { data } = stateVal;
    const errors = validate(data);
    setState(prevState => ({ ...prevState, errors }));
    if (!Object.keys(errors).length) {
      const globalSchool = getGlobalSchoolUtils();
      data.school = { schoolId: globalSchool.schoolId };
      setState(prevState => ({ ...prevState, loading: true }));
      props
        .updateUser({
          userId: props.loggedUserId,
          token: props.loggedUserToken,
          userRole: props.loggedUserRole,
          postData: data,
        })
        .then(() => {
          setState(prevState => ({ ...prevState, loading: false }));
          store.dispatch(showToast('Updated successfully', 'success'));
        })
        .catch(err => setError(err));
    }
  };

  const setError = err => {
    setState(prevState => ({
      ...prevState,
      errors: {
        global: formResMessage(err),
      },
      loading: false,
    }));
  };

  const validate = data => {
    const errors = {};

    if (validator.isEmpty(data.dateOfBirth.toString())) {
      errors.dateOfBirth = 'Date of birth cannot be empty';
    } else if (moment(data.dateOfBirth) > moment().subtract(21, 'years')) {
      errors.dateOfBirth = 'Invalid date of birth, Minimum age should be 21';
    }

    if (validator.isEmpty(data.qualification)) {
      errors.qualification = 'Qualification cannot be empty';
    }

    if (validator.isEmpty(data.totalExperience)) {
      errors.totalExperience = 'Total experience cannot be empty';
    }

    return errors;
  };

  const updatePassword = passwordData => {
    passwordData.email = props?.loggedUser?.email;
    return props.updatePassword({
      passwordData,
      token: props.loggedUserToken,
    });
  };

  const { userProfile } = props;
  const { data: user, errors, loading } = stateVal;
  return (
    <>
      <div className="content">
        <Row>
          <Col md="4">
            <Card className="card-user">
              <div className="image">
                <img alt="..." src={profileImgSrc} />
              </div>
              <CardBody>
                <div className="author">
                  <img
                    alt="..."
                    className="avatar border-gray"
                    src={require('../../../assets/img/default-avatar.png').default}
                  />
                  <h5 className="title" style={{ color: 'blue', fontSize: 18 }}>
                    {userProfile?.name}
                  </h5>
                  <h6>{userProfile?.email}</h6>
                  <p className="description">{userProfile?.designation}</p>
                </div>
              </CardBody>
            </Card>
          </Col>
          <Col md="8">
            <div className={classes.root}>
              <Paper square>
                <Tabs
                  value={value}
                  onChange={handleTabChange}
                  variant="fullWidth"
                  indicatorColor=""
                  textColor="inherit"
                  aria-label="icon label tabs example">
                  {[
                    { label: 'PROFILE', icon: <PersonPinIcon /> },
                    { label: 'CHANGE PASSWORD', icon: <LockOpenIcon /> },
                  ].map((el, i) => (
                    <Tab
                      key={i}
                      icon={el.icon}
                      label={el.label}
                      style={{
                        fontWeight: 'bold',
                        color: value === i ? buttonColor || buttonBorderColor : '',
                        borderBottom: value === i ? `3px solid ${buttonColor || buttonBorderColor}` : '',
                      }}
                    />
                  ))}
                </Tabs>
              </Paper>

              <TabPanel value={value} index={0}>
                <Card className="card-user">
                  <CardBody>
                    <Form>
                      {errors.global && (
                        <div className="mt-10 ml-15 mr-15 pad-12 alert alert-danger">{errors.global}</div>
                      )}
                      {user?.email?.includes('demo') && (
                        <>
                          <span style={{ color: 'orange' }}>Note: Demo user can&apos;t update profile information</span>
                          <br />
                        </>
                      )}
                      <Row>
                        <Col className="pr-1" md="6">
                          <FormGroup>
                            <label>Email</label>
                            <Input type="email" name="email" value={user?.email} disabled />
                          </FormGroup>
                        </Col>
                        <Col className="pl-1" md="6">
                          <FormGroup>
                            <label>Department</label>
                            <Input type="text" name="department" value={user?.department} disabled />
                          </FormGroup>
                        </Col>
                      </Row>
                      <Row>
                        <Col className="pr-1" md="6">
                          <FormGroup>
                            <label>Qualification</label>
                            <Input
                              type="text"
                              name="qualification"
                              onChange={handleChange}
                              value={user.qualification}
                              placeholder="Enter here..."
                              maxLength="50"
                              disabled={user?.email?.includes('demo')}
                            />
                            {errors.qualification && <span className="err-msg">{errors.qualification}</span>}
                          </FormGroup>
                        </Col>
                        <Col className="pl-1" md="6">
                          <FormGroup className="customDatePickerWidth">
                            <label>Date of birth</label>
                            <ReactDatePicker
                              className="form-control"
                              selected={user.dateOfBirth ? new Date(user.dateOfBirth) : null}
                              onChange={value => handleDateChange('dateOfBirth', value)}
                              dateFormat="dd/MM/yyyy"
                              showMonthDropdown
                              showYearDropdown
                              placeholderText="Select date..."
                              dropdownMode="select"
                              disabled={user?.email?.includes('demo')}
                            />
                            {errors.dateOfBirth && <span className="err-msg">{errors.dateOfBirth}</span>}
                          </FormGroup>
                        </Col>
                      </Row>
                      <Row>
                        <Col className="pr-1" md="6">
                          <FormGroup>
                            <label>Total experience</label>
                            <Input
                              type="text"
                              name="totalExperience"
                              onChange={handleChange}
                              value={user.totalExperience}
                              placeholder="Enter here..."
                              maxLength="50"
                              disabled={user?.email?.includes('demo')}
                            />
                            {errors.totalExperience && <span className="err-msg">{errors.totalExperience}</span>}
                          </FormGroup>
                        </Col>
                      </Row>
                      <Row>
                        <div className="update ml-auto mr-auto">
                          <CustomButton
                            className="btn-round"
                            type="submit"
                            disabled={loading || user?.email?.includes('demo')}
                            onClick={handleSubmit}
                            name="Update Profile"
                            loading={loading}
                          />
                        </div>
                      </Row>
                    </Form>
                  </CardBody>
                </Card>
              </TabPanel>
              <TabPanel value={value} index={1}>
                <ChangePassword updatePassword={updatePassword} email={user?.email} />
              </TabPanel>
            </div>
          </Col>
        </Row>
      </div>
    </>
  );
};

const mapStateToProps = state => {
  return {
    loggedUser: state.auth.loggedUser,
    loggedUserId: state.auth.loggedUserId,
    loggedUserToken: state.auth.loggedUserToken,
    loggedUserRole: state.auth.loggedUserRole,
    userProfile: state.auth.userProfile,
  };
};

const mapDispatchToProps = dispatch => {
  return {
    fetchUser: data => dispatch(fetchUserService(data)),
    updateUser: data => dispatch(updateUserService(data)),
    updatePassword: data => dispatch(updatePasswordService(data)),
  };
};

export default connect(mapStateToProps, mapDispatchToProps)(MyProfile);
